insert into ops.design_system (key, value, source) values ('chassis', '{"source_package":"handoff_longform/ (README.md + 4 fully-resolved inline-styled HTML exports, 1440px desktop, self-contained)","source_design_file":"Marsad Longform.dc.html","base_template":"1a","canvas":{"outer_body_background":"#e8e5dc","outer_body_layout":"display:flex; justify-content:center; margin:0; padding:0","page_shell_width_px":1440,"page_shell_background":"#fdfcf9","page_shell_text_color":"#14120e","page_shell_border":"1px solid #cfcabe","box_sizing":"border-box on all elements","page_horizontal_padding_px":34,"full_bleed_content_width_px":1372,"screen_label_attribute":"data-screen-label on the shell div"},"grid":{"stated_in_readme":"88px marker gutter | ~760px measure | 300px rail","as_built":"The exports implement the body as a 2-column CSS grid (measure + rail) inside a centred max-width container. The 88px marker gutter is a chassis rule, not a materialised grid column in these four files: no BLK-MARGIN / citation-anchor instance appears in any of the four pages, so no export needed the column. The whitespace left of the measure comes from centring the body container inside the 1440 shell (1a: 174px from shell edge to measure start; 3a/3b: 164px).","per_template_measured":{"1a":{"container_max_width":1160,"container_padding_x":34,"inner_width":1092,"grid_template_columns":"1fr 300px","column_gap":52,"measure_px":740,"rail_px":300},"1b":{"container_max_width":1160,"container_padding_x":34,"inner_width":1092,"grid_template_columns":"1fr 1fr (prose | exhibit) and full-width bands","column_gap":44,"measure_px":524,"rail_px":null},"3a":{"container_max_width":1180,"container_padding_x":34,"inner_width":1112,"grid_template_columns":"1fr 296px","column_gap":54,"measure_px":762,"rail_px":296},"3b":{"container_max_width":1180,"container_padding_x":34,"inner_width":1112,"grid_template_columns":"1fr 300px","column_gap":54,"measure_column_px":758,"measure_text_cap_px":740,"rail_px":300}},"recommended_build":"88px gutter | 740-762px measure | 296-300px rail, gaps 52-54px, all inside a 1160-1180px centred container with 34px page padding. Treat 740px as the canonical measure and 300px as the canonical rail.","gutter_role":"Not padding. Carries section markers, BLK-MARGIN notes and citation anchors that must align vertically to the paragraph they annotate.","measure_rule":"The measure is fixed. Body copy never reflows to the full 1440px. This is stated as the single most important thing to preserve.","exhibit_break_rule_stated":"Exhibits break the measure deliberately: charts and tables span gutter + measure, never the rail, so they read as evidence interrupting the argument rather than decoration beside it.","exhibit_break_rule_as_built":"Two mechanisms are visible: (1) exhibits placed inside the measure column run edge-to-edge of the measure with a full-bleed ink header bar (1a EXHIBIT 1/2/3, 3a EXHIBIT 1/2/3, 3b worked example); (2) genuinely measure-breaking exhibits are hoisted OUT of the body grid into their own full-container-width band (1b master exhibit and quarterly NIM table at 1092px; 3b timeline hero at 1112px). Neither mechanism ever intrudes on the rail column.","scroll_behaviour":"The rail is the only independently scrolling column: position:sticky; top:20px. Every other region scrolls with the page.","vertical_rhythm":{"body_paragraph_gap_px":[14,16,18,22,24,26],"exhibit_margin_top_px":[6,20,22,24],"section_subhead_margin_top_px":34,"chapter_rule_margin_top_px":[32,36],"footer_block_margin_top_px":26}},"fonts":{"loaded":"Google Fonts: Newsreader (ital,opsz 6..72,wght 400..800), Libre Franklin (300..800), IBM Plex Mono (400;500;600), Noto Naskh Arabic (400..700)","roles":{"Newsreader (serif)":"headlines, standfirsts, body copy, pull quotes, big stat values, chapter numbers/titles, related-item titles","Libre Franklin (sans)":"default body font-family of the document; UI labels, bullets, table cells, rail item text, buttons","IBM Plex Mono":"eyebrows, kickers, datelines, all numerics in tables/rails, provenance strips, agent chips, axis labels","Noto Naskh Arabic":"Arabic wordmark and Arabic company names"}},"type_scale":{"body_stated_in_readme":"Newsreader 17px / 1.72","body_as_built":{"1a":"19px / 1.68","1b":"17px / 1.66","3a":"19px / 1.68","3b":"18px / 1.68"},"body_color":"#26241f","h1":{"1a":"60px / 1.06, -0.022em, centred","1b":"44px / 1.10, -0.018em, left","3a":"58px / 1.06, -0.022em, left, reverse on ink","3b":"52px / 1.08, -0.020em, left"},"h1_common":"Newsreader 700, text-wrap:balance","standfirst":{"1a":"Newsreader 20/1.5 #57534a, max-width 780, centred","1b":"Newsreader 17.5/1.5 #57534a, max-width 660","3a":"Newsreader 20/1.5 #a8a396 on ink, max-width 820","3b":"Newsreader 19/1.52 #57534a inside an 840px block"},"drop_cap":"Newsreader 64px 700, float:left, line-height .78, padding 8px 12px 0 0 (1a opening paragraph; 3a chapter-one opening paragraph only)","section_subhead":{"1a":"Newsreader 25px 700, -0.012em","3b":"Newsreader 26px 700, -0.014em"},"chapter_heading":"number Newsreader 44px 700 #cfcabe line-height .9; eyebrow IBM Plex Mono 8.5px 600 .18em #8a857a; title Newsreader 30px 700 /1.16 -0.014em; block sits under a 2px #14120e top rule with 14px padding-top","pull_quote":{"1a_3a":"Newsreader 27px italic /1.38, -0.008em, 3px #14120e left rule, padding-left 26px","1b":"Newsreader 21px italic /1.42, -0.006em, 3px left rule, padding-left 22px"},"kicker":"IBM Plex Mono 9.5px 600, letter-spacing .2em, preceded by a 7-8px ink diamond (transform:rotate(45deg))","masthead_eyebrow":"IBM Plex Mono 9px 600, .18em, #57534a","dateline":"IBM Plex Mono 9px, .08em, #8a857a, margin-left:auto","rail_section_header":"10px 700, .18em, uppercase, border-bottom 2px #14120e, padding-bottom 8px","exhibit_header":"ink bar, padding 10px 16px; label IBM Plex Mono 9.5px 600 .16em; title 12px; right-aligned unit note IBM Plex Mono 8px #a8a396","provenance_strip":"padding 8px 16px, border-top 1px #dcd8cc, background #f6f4ee, 6px rotated diamond + IBM Plex Mono 8px .08em #57534a, optional right-aligned underlined action","footnote_line":"IBM Plex Mono 8-8.5px, #8a857a / #a8a396, line-height 1.7"},"color_tokens":{"ink":"#14120e","body_ink":"#26241f","text_mid":"#33302a","text_secondary":"#57534a","muted":"#8a857a","muted_light":"#a8a396","paper":"#fdfcf9","panel":"#f6f4ee","canvas":"#e8e5dc","fill_light":"#e3dfd4","rule_strong":"#dcd8cc","rule_light":"#efece3","border":"#cfcabe","reverse_text_on_ink":"#f6f4ee","rule_on_ink":"#26241f","positive":"#0a7a3c","positive_on_ink":"#4fc47f","positive_chip":"#0f5f31","warning_chip":"#c9a227","negative":"#c0342b"},"shared_components":{"masthead_strip":"height 46px, padding 0 34px, background #f6f4ee, border-bottom 1px #dcd8cc, gap 16px: Marsad wordmark (Newsreader 21px 700) [+ Arabic mark in 1a only] | 1x18px divider | section eyebrow | optional access pill | margin-left:auto dateline or series position","access_pill":"premium = IBM Plex Mono 8px 600 .1em, background #14120e, colour #f6f4ee, padding 2.5px 6px; free = same type with 1px #cfcabe border, colour #57534a, no fill","avatar_monogram":"circle 38-42px, 1.5px border, Newsreader 14-15px 600, two initials","action_button_secondary":"10.5px 600, 1px #cfcabe border, #57534a, padding 7px 12px","action_button_primary":"10.5px 700, .06em, background #14120e, colour #f6f4ee, padding 7px 13px, uppercase","exhibit_frame":"1px solid #14120e wrapper; ink header bar; #fdfcf9 body; optional provenance strip footer","provenance_diamond":"green #0a7a3c = verified filed/lake source; ink #14120e = Marsad desk model or desk computation","stat_strip":"flex row of equal cells, 1px #dcd8cc border, background #f6f4ee, cell padding 14px 18px; label IBM Plex Mono 8px .1em #8a857a; value Newsreader 27px 700","paywall_card":"2px solid #14120e, background #f6f4ee, padding 26px 30px, margin-top 6px","blur_teaser":"filter:blur(3.5px); pointer-events:none; user-select:none; with an absolutely positioned 120px linear-gradient scrim to #fdfcf9","method_disclosure_footer":"border-top 1px #dcd8cc, padding 14px 0 34px, two equal flex columns (METHOD | DISCLOSURE), label IBM Plex Mono 8px 600 .14em #8a857a, copy 11.5px /1.6 #57534a","agent_chip":"IBM Plex Mono 8px, 1px #cfcabe border, #57534a, padding 2px 6px, prefixed with a diamond glyph for agents; human bylines use a 1px #14120e border and no diamond","image_slot":"<image-slot id placeholder> custom element filling a fixed-height bordered box"},"conditional_flags":{"showProv":"default true; wraps every provenance strip (1a x3, 1b x2, 3a x2; absent in 3b)","showRail":"default true; wraps the whole sticky rail (1a, 3a, 3b; absent in 1b, which has no rail)","isFree":"default true; wraps the blurred teaser + paywall card (1a, 3a only)","isPremium":"default false; wraps the unblurred continuation + end-matter (1a, 3a only)","syntax":"<sc-if value=\"{{ flag }}\" hint-placeholder-val=\"{{ true|false }}\">"},"chassis_rules":["1a is the chassis; build it first. Everything else is furniture swaps on the same grid.","The measure is fixed and never reflows to the full 1440px.","The gutter is not padding; margin notes and citation anchors must align to the paragraph they annotate.","Exhibits span gutter + measure, never the rail.","The rail is the only independently scrolling (sticky) column.","Every figure cites a verified data-lake object; where a number is a desk computation rather than a company disclosure, the exhibit must say so.","Corrections are appended, never silent.","Analysts may not hold positions in covered names.","Standing disclosure: Marsad is research and data, not investment advice. Regulated by DFSA, Marsad FZ-LLC, DIFC.","Every visual unit is an instance of a BLK-* block from the 61-block library in handoff_article_blocks/; article templates are arrangements, blocks are the vocabulary.","Suggested build order: 1a chassis, then 3b, then 1b, then 3a."],"chassis_discrepancies":["README states body is Newsreader 17px/1.72; no export uses that pair (1a/3a 19/1.68, 1b 17/1.66, 3b 18/1.68). Treat 17/1.72 as the token and the per-type values as the shipped overrides, or reconcile before build.","README states an 88px marker gutter column; no export materialises it, because no page contains a BLK-MARGIN or citation-anchor instance.","README states the measure is ~760px; only 3a (762px) and 3b''s column (758px) match. 1a, the declared chassis, is 740px."]}'::jsonb, 'docs/design/article-templates.json')
on conflict (key) do update set value = excluded.value, source = excluded.source, updated_at = now();

insert into ops.design_system (key, value, source) values ('tokens', '{"colors":{"#e8e5dc":"page background (body) — the room the cards sit in","#fdfcf9":"card / paper surface; also the fill of hollow markers and the terminal colour of the premium-cut gradient","#f6f4ee":"inset panel, tinted table row, card-header bar, ''paper on paper''; also the paper-coloured text/inversion on ink","#efece3":"lightest hairline — chart gridlines, table row dividers, card-footer divider","#e3dfd4":"pale fill / meter track / stack tail segment / faint row rule","#dcd8cc":"standard card border and hairline rule; chart baseline / axis line","#cfcabe":"palest step of the ink ramp — chip hairline borders, rank numerals, wireframe body lines, donut smallest segment","#a8a396":"de-emphasised grey — faint mono notes, benchmark dashed series, greyed-out slope lines, waterfall start bar, annotation dashes, muted text on ink","#8a857a":"mono meta/label colour — every block footer, column headers, kickers; also the CLOSED freshness dot","#57534a":"secondary body text, muted table values, link hover; second step of the bar emphasis ramp","#33302a":"secondary prose / list-item text","#26241f":"serif running-prose ink","#14120e":"INK — the one accent. Primary text, family header bars, black header bars, rules, bar fills, borders on emphasis, inverted cards, CTA buttons, estimate column headers","#0a7a3c":"GREEN — direction only (positive/up/beat/verified diamond/LIVE dot). Never emphasis, never decoration","#c0342b":"RED — direction only (negative/down/miss/falsifier bullet/halt/1.0x cover line/critical timeline stage/withheld-figure border/FEED OFFLINE dot)","#c9a227":"AMBER — corrections (BLK-CORRECTION), DELAYED freshness state, degraded-feed flag in the venue header. Explicitly not red","#4fc47f":"green-on-ink variant — the upside figure inside the inverted BLK-VERDICT rating card (only occurrence)","#0f5f31":"deep green chip background — the YES branch label in BLK-DECISION (only occurrence)","#1f8a45":"dark-room heat ramp — strongest positive (BLK-HEAT only)","#1c6b38":"dark-room heat ramp — strong positive (BLK-HEAT only)","#1a5c32":"dark-room heat ramp — positive (BLK-HEAT only)","#203a27":"dark-room heat ramp — mild positive (BLK-HEAT only)","#232e22":"dark-room heat ramp — neutral (BLK-HEAT only)","#32241e":"dark-room heat ramp — mild negative (BLK-HEAT only)","#5c261f":"dark-room heat ramp — negative (BLK-HEAT only)","#7a291f":"dark-room heat ramp — strong negative (BLK-HEAT only)","rgba(20,18,14,.07)":"ink area-chart fill (BLK-AREA)","rgba(20,18,14,.16)":"ink bubble fill, emphasised point (BLK-SCATTER)","rgba(20,18,14,.08)":"ink bubble fill, de-emphasised point (BLK-SCATTER); ink annotation swatch","rgba(20,18,14,.06)":"ink annotation highlight on the wireframe document (BLK-ANATOMY)","rgba(192,52,43,.12)":"red bubble fill for a red-rated name (BLK-SCATTER)","rgba(192,52,43,.08)":"red annotation highlight on the wireframe document (BLK-ANATOMY)","rgba(253,252,249,0)":"transparent start of the premium-cut gradient, resolving to #fdfcf9 (BLK-CUT)"},"heat_ramp":{"note":"BLK-HEAT card states ''SAME 7-STOP RAMP AS THE SECTOR HEATMAP — NEVER INVENT A SECOND SCALE''; 8 distinct swatches are actually rendered in the specimen, listed here darkest-positive to darkest-negative","stops":["#1f8a45","#1c6b38","#1a5c32","#203a27","#232e22","#32241e","#5c261f","#7a291f"],"scope":"BLK-HEAT is the only block permitted to carry the dark-room palette on paper; scale is single-sourced with the sector heatmap (screen 1e)"},"ink_ramp":{"note":"monochrome emphasis ramp used by BLK-BARS, BLK-STACK, BLK-DONUT — darkest is always largest/lead","stops":["#14120e","#57534a","#a8a396","#cfcabe","#e3dfd4"]},"fonts":{"''Newsreader'', serif":"editorial display + running prose + big numerals (BLK-BIGNUM 60px, BLK-COUNTDOWN 36px, page title 32px, BLK-COVER 30px, stat values 24px, pull quote 21px italic, rank numerals 18px). Variable axes loaded: ital, opsz 6..72, wght 400..800 / italic 400..700","''Libre Franklin'', sans-serif":"document default set on body — UI/label/short-copy sans. Loaded wght 300..800, italic 400..600","''IBM Plex Mono'', monospace":"all metadata, kickers, column headers, chips, tabular numerals, block codes and every card footer. Loaded wght 400;500;600. 469 explicit uses — the highest-frequency family in the file","''Noto Naskh Arabic''":"loaded in the webfont link (wght 400..700) but not used by any specimen in this file"},"type_scale_px":{"7":"smallest wireframe kicker (BLK-ANATOMY document label)","8":"the workhorse mono meta size — every block footer, every column header, kickers, chips (258 uses)","9":"block code in the card header, mono chips, citation markers, rank/venue tags, breadth labels (89 uses)","10":"small CTA labels, pay-date cells","11":"table body values in mono, secondary descriptions (67 uses)","12":"table row labels, standard body copy, ticker mono in the rating card (47 uses)","13":"step headline, timeline date, estimate value","14":"delta figures in mono inside prose","15":"premium-cut teaser serif, margin-note prose, alert-CTA headline","16":"standard inline-block host prose (serif)","17":"tape headline, paywall headline, donut centre value","18":"league-table rank numeral","19":"company name inside the rating card","21":"pull quote; rating-card target and upside","24":"stat-strip value","30":"BLK-COVER headline multiple","32":"page title","36":"BLK-COUNTDOWN relative time","60":"BLK-BIGNUM","7.5":"SVG axis / in-chart tick labels, flow-diagram edge labels, heat-grid column headers","8.5":"freshness/halt/correction timestamps, thesis + falsify kickers, valuation-range scale labels","9.5":"step numerals (BLK-STEPS), data chips (BLK-CHIPROW)","10.5":"footnote lines, legend values, CTA button text, donut legend values","11.5":"card title in the header + primary short body copy (93 uses)","12.5":"comparison-grid values, league-table names","14.5":"myth assumption quote (italic serif)","15.5":"citation-chip host prose"},"font_weights":[400,600,700],"letter_spacing":{".2em":"family header bar label (A · INLINE etc.)",".18em":"paywall band kicker",".16em":"page eyebrow, rating-card kicker, thesis kicker, venue header",".14em":"section kickers inside specimens (MARSAD TAKE, HOW THIS WAS BUILT, SNAPSHOT, KEEP WATCHING THIS)",".12em":"timeline stage labels, halt/tape/conflict status chips",".1em":"the default mono label tracking — block codes, column headers, cell labels (86 uses)",".08em":"provenance stamp body, freshness labels",".06em":"every block-footer line; CTA button labels (65 uses)","-.006em":"pull quote (serif optical tightening)","-.016em":"page title","-.03em":"BLK-BIGNUM"},"line_heights":{"1.7":"the mono footer/meta default (84 uses)","1.5 / 1.55 / 1.6":"body copy","1.66 / 1.75 / 1.8 / 1.95":"serif running prose (1.95 when a sparkline is inline)","1.3 / 1.35 / 1.38 / 1.42":"display headlines and pull quote","1 / .86":"big numerals"},"three_hard_rules":["1. One accent only — ink. Green (#0a7a3c) and red (#c0342b) are reserved for *direction*, never for emphasis or decoration.","2. Every number carries a freshness state and a provenance stamp (BLK-FRESH, BLK-PROV).","3. A desk estimate is marked three ways at once — `E` suffix, ink column header, bold value — so it can never be mistaken for a filed figure. Never colour alone."],"accent_policy":{"ink":"#14120e is the only accent. All emphasis, hierarchy and decoration is ink or a step on the ink ramp.","green":"#0a7a3c — direction only: up/positive/beat/verified/LIVE. The arrow is semantic not literal (a falling cost of funds is green).","red":"#c0342b — direction only: down/negative/miss/halt/withheld/the 1.0x cover line/the one timeline stage that costs money/feed offline.","amber":"#c9a227 — corrections and degraded state only; a correction is integrity, so it is amber and never red.","second_accent":"prohibited — ''Never a second accent colour'' (D family header)."}}'::jsonb, 'docs/design/block-registry.json')
on conflict (key) do update set value = excluded.value, source = excluded.source, updated_at = now();

insert into ops.design_system (key, value, source) values ('families', '[{"key":"A","name":"Inline","header_label":"A · INLINE & SENTENCE-LEVEL","purpose":"Units that live inside a sentence: ticker chip, delta, citation chip, defined term, sparkline, margin note. Live inside running prose. No block borders, no vertical margin — they must not break the line rhythm.","count":6},{"key":"B","name":"Statement","header_label":"B · STATEMENT BLOCKS","purpose":"Where the desk commits to a view: thesis, pull quote, big number, rating card, gated Marsad Take, falsifiers. Each one takes a position — so each one is rules-checked and attributable to a human.","count":6},{"key":"C","name":"Tabular","header_label":"C · TABULAR","purpose":"Stat strip, facts grid, financials (with marked estimate column), scenarios, league table, beat/miss, ex-date row, transposed compare. Mono numerals, tabular-nums, hairline rows, black header bar. Estimate columns are always marked.","count":8},{"key":"D","name":"Charts","header_label":"D · CHARTS","purpose":"One shape per question — line, area, bars, proportional stack, waterfall, scatter, distribution, dumbbell, slope, valuation range, heat grid, rebased performance, donut, IPO cover meter, candles. Ink 2px lines, rgba(20,18,14,.07) fills, mono 8px axes, #efece3 gridlines, estimates in green or dashed. Never a second accent colour.","count":15},{"key":"E","name":"Mechanism","header_label":"E · MECHANISM & EXPLAINER","purpose":"Teach a process: timeline, steps, money flow, annotated document, worked example, assumption-vs-mechanism, if/then, glossary. Evergreen — they carry a review date, not a timestamp.","count":8},{"key":"F","name":"Wire & live state","header_label":"F · WIRE & LIVE STATE","purpose":"Timestamped and perishable: tape entry, chip row, snapshot, countdown, halt, correction, breadth, venue header. Timestamped, perishable, and honest about being stale. Every block here carries a clock.","count":8},{"key":"G","name":"Provenance & trust","header_label":"G · PROVENANCE & TRUST","purpose":"The audit trail rendered: lake stamp, build chain, freshness, desk-estimate marker, source conflict, rule applied. The family that makes agent-written journalism publishable. Not decoration — the audit trail, rendered.","count":6},{"key":"H","name":"Gates & CTAs","header_label":"H · GATES & CALLS TO ACTION","purpose":"Premium cut, paywall band, alert CTA, data download. Where the business model touches the page. They must never interrupt an argument mid-sentence.","count":4}]'::jsonb, 'docs/design/block-registry.json')
on conflict (key) do update set value = excluded.value, source = excluded.source, updated_at = now();

do $$ declare v int; begin
  select count(*) into v from ops.design_system;
  if v <> 3 then raise exception 'expected 3 design_system rows, got %', v; end if;
  raise notice 'design_system: %', v;
end $$;
